:root {
  --ocean: #1a6fa8;
  --ocean-light: #d6eaf8;
  --ocean-mid: #5b9ec9;
  --foam: #f0f8ff;
  --deck: #e8f4f0;
  --deck-border: #b2d8cc;
  --confirmed: #1e8a5e;
  --confirmed-bg: #d4f0e4;
  --text-dark: #1a2b3c;
  --text-mid: #4a6070;
  --text-light: #7a98aa;
  --pip-on: #1a6fa8;
  --pip-off: #ccdde8;
  --price-accent: #c95b1a;
  --card-bg: #ffffff;
}

article.charter-card {
  background: var(--card-bg);
  border: 2px solid var(--ocean-light);
  border-radius: 14px;
  width: 460px;
  overflow: hidden;
}

.charter-header {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--ocean);
  padding: 10px 14px;
}

.charter-badge {
  font-size: 24px;
  line-height: 1;
  flex-shrink: 0;
}

.charter-title {
  display: flex;
  flex-direction: column;
  gap: 1px;
  flex: 1;
}

.charter-title h2 {
  margin: 0;
  font-size: 15px;
  font-weight: 700;
  color: #ffffff;
  line-height: 1.2;
}

.charter-sub {
  font-size: 11px;
  color: var(--ocean-light);
  font-weight: 500;
}

.charter-status {
  background: var(--confirmed-bg);
  color: var(--confirmed);
  font-size: 10px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  flex-shrink: 0;
}

.charter-details {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border-bottom: 1px solid var(--ocean-light);
}

.detail-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 14px;
  border-right: 1px solid var(--ocean-light);
  border-bottom: 1px solid var(--ocean-light);
}

.detail-item:nth-child(even) {
  border-right: none;
}

.detail-item:nth-last-child(-n+2) {
  border-bottom: none;
}

.detail-label {
  font-size: 10px;
  color: var(--text-light);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.detail-value {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-dark);
}

.charter-crew {
  display: flex;
  background: var(--deck);
  border-bottom: 1px solid var(--deck-border);
}

.crew-slot {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 8px 0;
  flex: 1;
  border-right: 1px solid var(--deck-border);
}

.crew-slot:last-child {
  border-right: none;
}

.crew-avatar {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: var(--ocean-mid);
  color: #ffffff;
  font-size: 11px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid var(--ocean);
}

.crew-name {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-dark);
}

.crew-role {
  font-size: 10px;
  color: var(--text-mid);
}

.charter-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
  background: var(--foam);
}

.footer-guests {
  display: flex;
  align-items: center;
  gap: 7px;
}

.guests-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-light);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.guests-pips {
  display: flex;
  gap: 3px;
  align-items: center;
}

.pip {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--pip-off);
}

.pip.active {
  background: var(--pip-on);
}

.guests-count {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-dark);
}

.footer-price {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.price-label {
  font-size: 11px;
  color: var(--text-light);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.price-amount {
  font-size: 20px;
  font-weight: 800;
  color: var(--price-accent);
}
